	/* updateBuyerMdAmBudgetUpload */

 	UPDATE	ICOMBDGT
 	SET		PLAN_AMT = #{BUDGET_AMT},
 				PLAN_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'),
 				ADD_USER_ID = #{st_user_id}
 	WHERE	1=1
 	AND		BUYER = #{st_com_code}
 	AND		DEPT = #{BUDGET_DEPT}
 	AND		ACCOUNT_TYPE = #{ACCOUNT}
 	AND		TERM = #{st_term}
 	AND		TERM_TYPE = #{st_term_type}

