/* checkBuyerMdAmBudgetUploadAmt */ SELECT SUM(X.PLAN_AMT) AS PLAN_AMT, SUM(X.USED_AMT) AS USED_AMT FROM ( SELECT TO_NUMBER(#{BUDGET_AMT}) AS PLAN_AMT, RESULT_AMT + TEMP_AMT AS USED_AMT FROM ICOMBDGT WHERE BUYER = #{st_com_code} AND DEPT = #{BUDGET_DEPT} AND ACCOUNT_TYPE = #{ACCOUNT} AND TERM = #{st_term} AND TERM_TYPE = #{st_term_type}
UNION ALL
SELECT 0 AS PLAN_AMT, 0 AS USED_AMT FROM DUAL ) X
